pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { c = new C(); }

    // fuzzed param: candidate newOwner (the fuzzer will supply many addresses)
    function testFuzz_property(address newOwner) public {
        // keep domain wide: disallow zero address as a fuzzed input is allowed but we still test it
        // (we do not exclude address(0) because property should hold even for that value)

        // The original contract sets `owner = _owner` when called by admin (deployer).
        // c was deployed in setUp() by this test contract, so the deployer (msg.sender in constructor)
        // is this test contract. But in the reference, constructor sets owner = msg.sender (the test).
        // setOwner requires onlyAdmin where admin was set to the deployer (the test contract) too.
        // So we must call setOwner as the admin (this contract). Use vm.prank to act as the admin.

        // Call setOwner through this test contract (which is the admin) to set to newOwner.
        // No vm.assume to keep fuzz wide.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: if the call succeeded, the public getter owner() must equal the supplied newOwner.
        // (This reads c.owner(), a public getter.)
        // For the correct contract, for ALL newOwner inputs where the call succeeds, owner() == newOwner.
        // The mutant breaks this by setting owner = address(0) even when the call succeeds.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, assert that it indeed reverted (ok == false) — but we must make a single assertTrue
            // The universal property targeted is about successful completion; however we still must emit exactly one assertTrue.
            // To satisfy the test structure, when call reverted we assert that c.owner() != newOwner would be false in ref,
            // but to keep exactly one assertTrue for all runs, we assert that either the call succeeded and owner==newOwner,
            // or the call failed (which shouldn't happen in normal conditions). The reference never reverts here,
            // so this branch should not be hit; still we produce a single assertTrue by checking ok == true.
            // Since the instructions require exactly one assertTrue, unify into one assertion below.
            assertTrue(ok == true);
        }
    }
}

