pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: actor (an attacker address) and newOwner (the address to set)
    function testFuzz_property(address actor, address newOwner) public {
        // keep addresses wide but non-zero for clarity
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        // admin is deployer (this test contract), as c was deployed in setUp()
        address admin = address(this);

        // Step 1: admin sets owner to actor (this is allowed in both reference and mutant)
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // Expect setOwner to succeed when called by admin (deployer)
        // if this fails the test environment is wrong; assume it succeeded
        vm.assume(ok);

        // Now actor (current owner) attempts to call setOwner to set owner to newOwner
        // In the reference contract onlyAdmin limits to admin, so this should revert when called by actor.
        // In the mutant, onlyAdmin compares to owner, so actor (being owner) can succeed.
        vm.prank(actor);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion: after the actor's attempt, the owner must not have changed from actor.
        // In the reference, actor's call should fail and owner remains actor -> ok2 == false and c.owner() == actor.
        // In the mutant, actor's call may succeed and owner() == newOwner (different) -> violating this assertion for some inputs.
        assertTrue(c.owner() == actor);
    }
}

