import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;
    function setUp() public { 
        // deployer is the test contract by default, but we capture an EOA address to act as non-admin
        c = new C();
        deployer = address(this);
    }

    // Fuzz parameter is an arbitrary address that the fuzzer will try to use as a non-admin caller
    function testFuzz_property(address attacker) public {
        // Avoid the trivial case where the attacker is the admin/deployer (address(this))
        // Keep domain wide: only exclude the admin so we exercise non-admin behavior
        vm.assume(attacker != address(this));

        // The property: only admin can successfully call setOwner. We will have attacker attempt to call setOwner
        // If the reference contract is used, the call by attacker must revert (i.e., not complete). We capture completion as ok.

        bool ok;
        // fuzzed newOwner can be any address; use attacker as the proposed owner to keep inputs simple
        address newOwner = attacker;

        // make the call as the attacker
        vm.prank(attacker);
        try c.setOwner(newOwner) returns (bool res) {
            // call completed
            ok = true;
        } catch {
            // call reverted
            ok = false;
        }

        // AssertTrue: for all attacker != deployer, the reference contract requires only admin, so call must revert (ok == false)
        // The mutant that removes the require will make ok == true for some attacker, causing this assertion to fail.
        assertTrue(!ok);
    }
}

