pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor is a potential caller trying to change owner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid the zero address for clarity
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        bool ok;
        // simulate caller trying to call setOwner
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: only the deployer (admin) can change owner.
        // setUp() deployed c from this test contract, so the admin is address(this).
        // Therefore, for any fuzzed caller that is NOT address(this), the call must fail (ok == false).
        // For caller == address(this), the call may succeed (ok == true).
        // This single assertion captures that invariant by checking that if the caller is not the admin,
        // then c.setOwner did not succeed.
        if (caller != address(this)) {
            assertTrue(ok == false);
        } else {
            // admin may change owner; ensure the call succeeded when admin called
            assertTrue(ok == true);
        }
    }
}

