pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (who attempts to call setOwner) and candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Keep addresses wide but avoid the zero-address for clarity
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure caller is not the deployer/admin to test that only admin can change owner.
        // The deployer/admin is address(this) at deployment time inside setUp(), which is this test contract;
        // however C's constructor set owner/admin to msg.sender (the test contract). The admin is the test contract
        // address. We need a distinct EOA to act as 'caller'. Ensure caller != address(this).
        vm.assume(caller != address(this));

        // Fund the caller so it can make calls if needed (not strictly necessary here)
        vm.deal(caller, 1 ether);

        // Try to have 'caller' invoke setOwner(newOwner). Capture whether the call succeeded.
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the caller is NOT the deployer/admin, then the call must NOT succeed
        // and thus c.owner() must remain equal to the original deployer (this contract). We observe via the public getter.
        address observedOwner = c.owner();

        // Only one assertion reading c: reference C guarantees that for any caller != deployer, setOwner cannot
        // be successfully invoked by that caller, so either the call reverted (ok == false) OR the owner stayed equal
        // to the deployer (address(this)). The reference will ensure owner == address(this). The mutant allows a
        // non-admin caller to change owner, so for some inputs this assertion will fail on the mutant.
        assertTrue(observedOwner == address(this));
    }
}
